INSERT INTO products (name, brand, product_type, description, image_url)
SELECT a.name, a.brand, a.product_type, a.description, a.image_url
FROM additions a
WHERE NOT EXISTS (
    SELECT 1 FROM products p
    WHERE lower(trim(p.name)) = lower(trim(a.name))
      AND lower(trim(coalesce(p.brand, ''))) = lower(trim(a.brand))
);
-- END CURATED AMAZON CATALOG ADDITIONS
